
package com.utahfoodbank.database

import com.utahfoodbank.model.Client

// Ktorm schema imports
import org.ktorm.schema.Table
import org.ktorm.schema.int
import org.ktorm.schema.varchar
import org.ktorm.schema.double

// Ktorm database operation imports
import org.ktorm.dsl.from
import org.ktorm.dsl.select
import org.ktorm.dsl.map
import org.ktorm.dsl.insert
import org.ktorm.dsl.update
import org.ktorm.dsl.delete
import org.ktorm.dsl.eq

// Represent our SQLite "clients" table in Kotlin
object Clients : Table<Nothing>("clients") {

    // Primary key automatically generated by SQLite
    val id = int("client_id").primaryKey()

    // Existing client information
    val clientName = varchar("client_name")
    val clientAddress = varchar("client_address")
    val clientCity = varchar("client_city")
    val clientZipCode = varchar("client_zip_code")

    // NEW: Geographic coordinates for route optimization
    // These must match our SQLite column names
    val latitude = double("latitude")
    val longitude = double("longitude")
}


// GET: Retrieve all clients from SQLite
fun getClients(): List<Client> {

    return database
        .from(Clients)
        .select()
        .map { row ->

            Client(
                clientId = row[Clients.id]!!,
                clientName = row[Clients.clientName]!!,
                clientAddress = row[Clients.clientAddress]!!,
                clientCity = row[Clients.clientCity]!!,
                clientZipCode = row[Clients.clientZipCode]!!,

                // NEW: Read coordinates from SQLite
                // Unlike clientId, these may be NULL
                latitude = row[Clients.latitude],
                longitude = row[Clients.longitude]
            )
        }
}


// POST: Insert a new client into SQLite
fun addClient(client: Client) {

    database.insert(Clients) {

        set(Clients.clientName, client.clientName)
        set(Clients.clientAddress, client.clientAddress)
        set(Clients.clientCity, client.clientCity)
        set(Clients.clientZipCode, client.clientZipCode)

        // NEW: Save coordinates if available
        // SQLite accepts NULL for these columns
        set(Clients.latitude, client.latitude)
        set(Clients.longitude, client.longitude)
    }
}


// DELETE: Remove a client using their ID
fun deleteClient(clientId: Int): Int {

    return database.delete(Clients) {
        it.id eq clientId
    }
}



// PUT: Update an existing client
fun updateClient(clientId: Int, client: Client): Int {

    // Retrieve the existing client before updating
    val existingClient = getClients().find {
        it.clientId == clientId
    } ?: return 0

    // Check whether the client's address has changed
    val addressChanged =
        existingClient.clientAddress != client.clientAddress ||
                existingClient.clientCity != client.clientCity ||
                existingClient.clientZipCode != client.clientZipCode

    // Update the client in SQLite
    return database.update(Clients) {

        // Update basic client information
        set(Clients.clientName, client.clientName)
        set(Clients.clientAddress, client.clientAddress)
        set(Clients.clientCity, client.clientCity)
        set(Clients.clientZipCode, client.clientZipCode)

        if (addressChanged) {

            // Address changed, so old coordinates are invalid
            // Clear them until the new address is geocoded
            set(Clients.latitude, null)
            set(Clients.longitude, null)

        } else if (
            client.latitude != null &&
            client.longitude != null
        ) {

            // Address unchanged and coordinates were provided
            set(Clients.latitude, client.latitude)
            set(Clients.longitude, client.longitude)
        }

        // If the address hasn't changed and no coordinates
        // were supplied, preserve the existing coordinates

        // Update only the client matching this ID
        where {
            it.id eq clientId
        }
    }
}


// Update only a client's geographic coordinates.
// This avoids changing their name or address.
fun updateClientCoordinates(
    clientId: Int,
    latitude: Double,
    longitude: Double
): Int {

    return database.update(Clients) {

        // Save coordinates returned by GeocodingService
        set(Clients.latitude, latitude)
        set(Clients.longitude, longitude)

        // Update only the specified client
        where {
            it.id eq clientId
        }
    }
}
